# Each slide uses two spoken chunks, with one explicit pause/reading hold between them.
def s(title, section, text, after, pause=2, cue='', source='', takeaway='', backup=False):
 return dict(title=title, section=section, spoken=[text,after], pause=pause, cue=cue, source=source, takeaway=takeaway, backup=backup, wpm=120)
